CREATE TABLE public."Screen_Visibility_Rules" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),screen text NOT NULL,scope text NOT NULL CHECK(scope IN ('all','role','education','team','committee','user')),value text NOT NULL DEFAULT '',visible boolean NOT NULL DEFAULT true,updated_by text NOT NULL,UNIQUE(screen,scope,value)); GRANT ALL ON public."Screen_Visibility_Rules" TO service_role; ALTER TABLE public."Screen_Visibility_Rules" ENABLE ROW LEVEL SECURITY;